const students = [
  { id: 1, name: 'Morolake', program: 'Software Development', gpa: 3.8 },
  { id: 2, name: 'Tega', program: 'Network Security', gpa: 3.2 },
  { id: 3, name: 'Ama', program: 'Software Development', gpa: 2.9 },
  { id: 4, name: 'Liam', program: 'Data Science', gpa: 3.6 },
  { id: 5, name: 'Priya', program: 'Software Development', gpa: 3.9 },
  { id: 6, name: 'Noah', program: 'Network Security', gpa: 2.4 },
];
const enrollments = [
  { studentId: 1, course: 'CPRG 304', grade: 'A' },
  { studentId: 1, course: 'CPRG 307', grade: 'B+' },
  { studentId: 2, course: 'CPRG 304', grade: 'B' },
  { studentId: 3, course: 'CPRG 304', grade: 'C' },
  { studentId: 5, course: 'CPRG 307', grade: 'A+' },
  { studentId: 7, course: 'CPRG 304', grade: 'A' },
];

const rows = students.map(s => {
  const courses = enrollments
    .filter(e => e.studentId === s.id)
    .map(e => e.course);
  return courses.length
    ? courses.map(c => s.name + ' - ' + c)
    : [s.name + ' - none'];
}).flat();
console.log(JSON.stringify(rows));

